shopifyProfiles.query:
query {
 deliveryProfiles(first: 5) {
  nodes {
   id name default coversAllItems activeMethodDefinitionsCount locationsWithoutRatesCount zoneCountryCount
   profileLocationGroups {
    locationGroupZones(first: 10) {
     nodes {
      zone { id name countries { code { countryCode restOfWorld } name } }
      methodDefinitionCounts { rateDefinitionsCount participantDefinitionsCount }
      methodDefinitions(first: 10) {
       nodes {
        id name active description methodConditions { field operator conditionCriteria { ... on MoneyV2 { amount currencyCode } ... on Weight { value unit } } }
        rateProvider {
         __typename
         ... on DeliveryRateDefinition { price { amount currencyCode } }
         ... on DeliveryParticipant {
          fixedFee { amount currencyCode }
          carrierService { name formattedName active availableServicesForCountries(restOfWorld: false) { name countries { countryCodes restOfWorld } } }
          participantServices { name active }
         }
        }
       }
      }
     }
    }
   }
  }
 }
}

exactNailVariantProfile.query:
query {
 product(id:"gid://shopify/Product/15500073730433") {
  id title
  variants(first: 1) { nodes { id deliveryProfile {
   id name default coversAllItems activeMethodDefinitionsCount locationsWithoutRatesCount zoneCountryCount
   profileLocationGroups { locationGroupZones(first: 10) { nodes {
    zone { name countries { code { countryCode restOfWorld } name } }
    methodDefinitions(first: 10) { nodes {
     name active methodConditions { field operator conditionCriteria { ... on MoneyV2 { amount currencyCode } } }
     rateProvider { __typename ... on DeliveryRateDefinition { price { amount currencyCode } } }
    } }
   } } }
  } } }
 }
